// Takes Claude's edit out of its reply, fixes what is safe to fix, and lists anything else,
// so Claude can fix it before Shotstack spends anything.
const attempt = $json.attempt;
const answer = String($json.text ?? '');
const problems = [];
let edit = null;
try {
  edit = JSON.parse(answer.slice(answer.indexOf('{'), answer.lastIndexOf('}') + 1));
} catch (e) {
  problems.push(answer.trim().endsWith('}')
    ? `The reply is not one valid JSON object (${e.message}).`
    : 'The reply was cut off before the JSON ended. Write a more compact edit.');
}
if (edit) {
  edit.output = { format: 'mp4', size: { width: 1080, height: 1920 }, fps: 30 };
  const clips = (edit.timeline?.tracks ?? []).flatMap((t) => t.clips ?? []);
  if (!clips.length) problems.push('The timeline has no clips.');
  if (clips.some((k) => ['image', 'video'].includes(k.asset?.type) && !k.asset?.prompt)) problems.push('Use only generated images and videos: no stock media.');
  // Room around the brief's 8 images and 3 video shots, and a cap on what they cost.
  const images = clips.filter((k) => k.asset?.type === 'image' && k.asset?.prompt).length;
  if (images < 4 || images > 10) problems.push(`Generate 8 images, not ${String(images)}.`);
  const videos = clips.filter((k) => k.asset?.type === 'video' && k.asset?.prompt);
  if (videos.length > 3) problems.push(`Generate 3 videos at most, not ${videos.length}.`);
  if (videos.some((k) => !(Number(k.length) <= 5))) problems.push('Give each generated video a length of 4 seconds.');
  // Generated videos come with their own sound. Here the music and the voice carry the sound.
  for (const k of clips) if (k.asset?.type === 'video') k.asset.volume = 0;
  const music = clips.filter((k) => k.asset?.type === 'audio' && k.asset?.model === 'elevenlabs-music');
  if (music.length !== 1) problems.push('Use exactly one music clip generated with elevenlabs-music.');
  // Composition plans fail at Shotstack today (9 Oct 2026), so the plain prompt is used instead.
  for (const m of music) if (m.asset.options?.compositionPlan) delete m.asset.options.compositionPlan;
  // The guide offers "full" as a rich-text animation style, but Shotstack takes only these two (9 Oct 2026).
  for (const k of clips) if (k.asset?.type === 'rich-text' && k.asset.animation?.style && !['character', 'word'].includes(k.asset.animation.style)) delete k.asset.animation.style;
  // Heavy uppercase captions with an outline run together without extra letter spacing.
  for (const k of clips) if (k.asset?.type === 'rich-caption') k.asset.style = { ...k.asset.style, letterSpacing: Math.max(4, Number(k.asset.style?.letterSpacing) || 0) };
  if (!clips.some((k) => k.alias === 'voice' && k.asset?.type === 'audio' && k.asset?.prompt)) {
    problems.push('Add the voiceover: an audio clip with the alias "voice" generated with elevenlabs-multilingual-v2.');
  }
  if (!clips.some((k) => k.asset?.type === 'rich-caption' && k.asset?.src === 'alias://voice')) {
    problems.push('Add the captions: a rich-caption clip with src "alias://voice".');
  }
  const end = Math.max(0, ...clips.map((k) => (typeof k.start === 'number' && typeof k.length === 'number' ? k.start + k.length : 0)));
  if (end > 40) problems.push(`The video runs ${String(end)} seconds: keep it to 32.`);
}
return [{ json: { edit, problems: problems.join(' '), attempt } }];
